{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "Background Despite advances made in curbing the global malaria burden since the 2000s, progress has stalled, in part due to a plateauing of the financing available to implement needed interventions. In 2020, approximately 3.3 billion USD was invested globally for malaria interventions, falling short of the targeted 6.8 billion USD set by the GTS, increasing the financial gap between desirable and actual investment.",
      "reason": "The abstract describes the current state of knowledge (progress has stalled; financing shortfall) and thus frames important uncertainties relevant to optimisation models for malaria control."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "Models for malaria control optimization are used to disentangle the most efficient interventions or packages of interventions for inherently constrained budgets. This systematic review aimed to identify and characterise models for malaria control optimization for resource allocation in limited resource settings and assess their strengths and limitations.",
      "reason": "The abstract explicitly states the rationale and importance of the review (need to identify and characterise models to inform resource allocation under constrained budgets) and explains why the review is needed."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No evidence was found in the provided text that discusses existing similar systematic reviews, cites previous reviews, or explains why this review is needed as an update or replication."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_2",
      "quote": "Models for malaria control optimization are used to disentangle the most efficient interventions or packages of interventions for inherently constrained budgets.",
      "reason": "The review focuses on models for optimisation of malaria control rather than being a review of intervention effects; therefore describing mechanisms of action of interventions is not applicable to this review."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_2",
      "quote": "This systematic review aimed to identify and characterise models for malaria control optimization for resource allocation in limited resource settings and assess their strengths and limitations.",
      "reason": "No logic model or discussion of hypothesised relationships between intervention components and outcomes is expected or provided because the review concerns optimisation models rather than evaluation of complex intervention delivery; thus the logic-model requirement is not applicable."
    }
  ],
  "confidence": 80
}

