{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PARTIAL",
      "chunk_id": "text_7",
      "quote": "Each record in the search were included if they met all of the following criteria: (1) Were scientific peer-reviewed journals written in English; (2) Were published before 30th June 2024; (3) Studies were included irrespective of the targeted geographical regions; (4) Studies were included irrespective of the population subgroups; (5) Studies containing an optimization model (mathematical or statistical); (6) All studies with human Plasmodium species; (7) Studies with two or more interventions; (8) Cost data were used in combination with the model outputs; (9) Outcomes/health benefits were clearly stated and/or measured.",
      "reason": "The manuscript lists multiple study characteristics used for eligibility (language, date, region, population, presence of optimization model, Plasmodium species, number of interventions, cost data, outcomes). It does not explicitly specify eligible study designs in depth (beyond 'scientific peer-reviewed journals') or any follow-up requirements, so the element is only partially satisfied."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "(1) Were scientific peer-reviewed journals written in English; (2) Were published before 30th June 2024;",
      "reason": "The report characteristics eligibility are explicitly stated: inclusion limited to peer-reviewed journals, English language, and published before 30 June 2024."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": "text_9",
      "quote": "The following records were excluded: (1) Editorials, commentaries, opinion papers, conference abstracts, media reports, letters, bulletins, pre-prints, grey literature; (2) Non-English language studies; (3) Systematic reviews, meta-analyses.",
      "reason": "Although exclusion categories are listed, the review does not distinguish exclusions because outcomes were not measured from exclusions because outcome results were not reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "table_1",
      "quote": "Region of focus ... Africa 8 (53.3) ... Asia 4 (26.7) ... Number of interventions per article ... 2 3 (20.0) ... 3 3 (20.0) ... Population used in optimization ... General population 14 (93.3) ... Administrative level of data analysis ... National 13 (86.7) ... Subnational 9 (66.7)",
      "reason": "The synthesis groups are specified (e.g., region of focus, number/types of interventions, population used, administrative level, model types) and these groups are presented in the summary tables and narrative, linking studies into these categories for synthesis."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "MISSING",
      "chunk_id": "text_6",
      "quote": "The databases PubMed and Embase (OVID) were searched for relevant studies ... A detailed list of all search terms and results are available in Additional file 2.",
      "reason": "The manuscript reports the search sources and criteria but does not provide explicit rationales for notable restrictions on study eligibility (for example, why non-English studies or grey literature were excluded). No justification for these notable restrictions is given in the provided evidence."
    }
  ],
  "confidence": 85
}

